import numpy as np
def minper(gi):
    H,W=gi.shape
    n=int(Counter(gi.flatten()).most_common(1)[0][0])
    best=None
    for pr in range(1,H+1):
        for pc in range(1,W+1):
            vals={}
            ok=True
            for r in range(H):
                for c in range(W):
                    if gi[r,c]==n: continue
                    k=(r%pr,c%pc)
                    if k in vals and vals[k]!=int(gi[r,c]): ok=False;break
                    vals[k]=int(gi[r,c])
                if not ok: break
            if ok:
                sc=pr*pc
                if best is None or sc<best[0]: best=(sc,vals,pr,pc)
    return best[:3],best[1]
